create table public.roster_slot_definitions(id uuid primary key default gen_random_uuid(),season_id uuid not null references public.seasons(id) on delete cascade,label text not null,slot_count integer not null check(slot_count>=0),eligible_positions text[] not null default '{}',kind text not null check(kind in('starter','bench','ir')));
create table public.position_limits(id uuid primary key default gen_random_uuid(),season_id uuid not null references public.seasons(id) on delete cascade,position text not null,maximum integer check(maximum is null or maximum>=0),unique(season_id,position));
create table public.draft_configurations(season_id uuid primary key references public.seasons(id) on delete cascade,team_count integer not null check(team_count>1),snake boolean not null,rounds integer not null check(rounds>0),pick_timer_seconds integer check(pick_timer_seconds is null or pick_timer_seconds>=0),keeper_count integer not null check(keeper_count>=0),live_start_round integer not null check(live_start_round>=1),pick_trading_enabled boolean not null,order_status text not null check(order_status in('unassigned','assigned','locked')));
create table public.draft_slots(id uuid primary key default gen_random_uuid(),season_id uuid not null references public.seasons(id) on delete cascade,slot integer not null check(slot>0),original_team_id uuid not null references public.season_teams(id),unique(season_id,slot),unique(season_id,original_team_id));
create table public.pick_ownership(id uuid primary key default gen_random_uuid(),season_id uuid not null references public.seasons(id) on delete cascade,round integer not null check(round>0),slot integer not null check(slot>0),original_team_id uuid not null references public.season_teams(id),current_team_id uuid not null references public.season_teams(id),unique(season_id,round,slot));
create table public.keeper_assignments(id uuid primary key default gen_random_uuid(),season_id uuid not null references public.seasons(id) on delete cascade,team_id uuid not null references public.season_teams(id),keeper_slot integer not null check(keeper_slot>0),temporary_player_id text not null,canonical_player_id uuid,display_name text not null,normalized_name text not null,status text not null check(status in('provisional','locked')),unique(season_id,team_id,keeper_slot),unique(season_id,normalized_name));
create table public.keeper_lock_states(season_id uuid primary key references public.seasons(id) on delete cascade,status text not null check(status in('provisional','locked')),deadline timestamptz,locked_at timestamptz,locked_by uuid references auth.users(id),audit jsonb not null default '[]');
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['roster_slot_definitions','position_limits','draft_configurations','draft_slots','pick_ownership','keeper_assignments','keeper_lock_states'] LOOP EXECUTE format('alter table public.%I enable row level security',t);EXECUTE format('create policy "private owner %1$s" on public.%1$I for all to authenticated using(exists(select 1 from public.seasons s join public.leagues l on l.id=s.league_id join public.draft_allowed_users a on a.user_id=auth.uid() where s.id=season_id and l.owner_id=auth.uid())) with check(exists(select 1 from public.seasons s join public.leagues l on l.id=s.league_id join public.draft_allowed_users a on a.user_id=auth.uid() where s.id=season_id and l.owner_id=auth.uid()))',t);END LOOP;END$$;
